import 'package:json_object_mapper/json_object_mapper.dart';
class User extends JSONObject{String username;String email;User.fromFields(this.username,this.email);User.fromJson(String json){initializeFromJson(json);} @override String toString()=>"User{username: $username, email: $email}";}
void main(){var u=User.fromFields('joe','joe@mail.com');print(u.toJson());}
